package io.beep.core.adapter.out.postgres;

import io.beep.core.app.port.EcosystemRepository;
import io.beep.core.app.conversion.DeveloperUseCase.EventCommand;
import io.beep.core.domain.DomainException;
import io.beep.core.domain.team.WorkspaceRole;
import io.beep.core.domain.ecosystem.RadarPolicy;
import java.time.*;
import java.util.*;
import org.jooq.DSLContext;
import org.jooq.Record;
import org.jooq.JSONB;

/** All dynamic values are bound; table names below are fixed application constants. */
public class PostgresEcosystemAdapter implements EcosystemRepository {
  private final DSLContext db;
  public PostgresEcosystemAdapter(DSLContext db){this.db=db;}
  private static OffsetDateTime at(Instant t){return t==null?null:t.atOffset(ZoneOffset.UTC);}
  private static Instant time(Record r,String col){var v=r.get(col,OffsetDateTime.class);return v==null?null:v.toInstant();}
  private long count(String sql,Object... args){return ((Number)db.fetchValue(sql,args)).longValue();}
  private List<Map<String,Object>> rows(String sql,Object... args){return db.fetch("SELECT to_jsonb(q) AS data FROM ("+sql+") q",args).map(r->Sql.map(r.get("data",JSONB.class)));}
  private void changed(int n){if(n==0)throw new DomainException("not_found");}
  @Override public UUID createWorkspace(UUID owner,String name,Instant now){db.execute("SELECT 1 FROM users WHERE id=? FOR UPDATE",owner);if(count("SELECT count(*) FROM workspaces WHERE owner_id=?",owner)>=10)throw new DomainException("quota_reached");return db.fetchOne("INSERT INTO workspaces(id,owner_id,name,plan_code,status,created_at,personal) VALUES(gen_random_uuid(),?,?,'starter','active',?::timestamptz,false) RETURNING id",owner,name,at(now)).get("id",UUID.class);}
  @Override public Optional<WorkspaceRole> role(UUID w,UUID u){return db.fetchOptional("SELECT CASE WHEN owner_id=? THEN 'owner' ELSE (SELECT role FROM workspace_members WHERE workspace_id=w.id AND user_id=?) END AS role FROM workspaces w WHERE id=?",u,u,w).map(r->r.get("role",String.class)).map(WorkspaceRole::parse);}
  @Override public boolean canAccess(UUID w,UUID u){return Boolean.TRUE.equals(db.fetchValue("WITH ranked AS (SELECT user_id,row_number() OVER(ORDER BY created_at,user_id) AS seat FROM workspace_members WHERE workspace_id=?) SELECT EXISTS(SELECT 1 FROM workspaces w LEFT JOIN ranked m ON m.user_id=? WHERE w.id=? AND (w.owner_id=? OR (beep_effective_right(w.id,'features.teams')=1 AND m.user_id IS NOT NULL AND (beep_effective_right(w.id,'members.max')=-1 OR m.seat<beep_effective_right(w.id,'members.max')))))",w,u,w,u));}
  @Override public List<Map<String,Object>> workspaces(UUID u){return rows("SELECT id,name,plan_code AS plan,CASE WHEN owner_id=? THEN 'owner' ELSE m.role END AS role FROM workspaces w LEFT JOIN workspace_members m ON m.workspace_id=w.id AND m.user_id=? WHERE owner_id=? OR m.user_id IS NOT NULL ORDER BY w.created_at",u,u,u);}
  @Override public Map<String,Object> team(UUID w){var out=new LinkedHashMap<String,Object>();out.put("members",rows("SELECT u.id,u.email,'owner' AS role FROM users u JOIN workspaces w ON w.owner_id=u.id WHERE w.id=? UNION ALL SELECT u.id,u.email,m.role FROM workspace_members m JOIN users u ON u.id=m.user_id WHERE m.workspace_id=?",w,w));out.put("invitations",rows("SELECT id,email,role,expires_at FROM team_invitations WHERE workspace_id=? AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at>now() ORDER BY created_at",w));long active=1+count("SELECT count(*) FROM workspace_members WHERE workspace_id=?",w);out.put("activeSeats",active);out.put("seats",active+count("SELECT count(DISTINCT email) FROM team_invitations i WHERE workspace_id=? AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at>now() AND NOT EXISTS(SELECT 1 FROM workspace_members m JOIN users u ON u.id=m.user_id WHERE m.workspace_id=i.workspace_id AND u.email=i.email)",w));return out;}
  @Override public void invite(Invite i){
    if(count("SELECT count(*) FROM users u JOIN workspaces w ON w.id=? WHERE u.email=? AND (u.id=w.owner_id OR EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w.id AND user_id=u.id))",i.workspace(),i.email())>0)throw new DomainException("conflict");
    db.execute("UPDATE team_invitations SET revoked_at=now() WHERE workspace_id=? AND email=? AND accepted_at IS NULL AND revoked_at IS NULL",i.workspace(),i.email());
    db.execute("INSERT INTO team_invitations(id,workspace_id,email,role,token_hash,expires_at) VALUES(?,?,?,?,?,?::timestamptz)",i.id(),i.workspace(),i.email(),i.role(),i.tokenHash(),at(i.expiresAt()));
  }
  @Override public Optional<Invite> invitation(String hash,Instant now){return db.fetchOptional("SELECT * FROM team_invitations WHERE token_hash=? AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at>?::timestamptz",hash,at(now)).map(r->new Invite(r.get("id",UUID.class),r.get("workspace_id",UUID.class),r.get("email",String.class),r.get("role",String.class),r.get("token_hash",String.class),time(r,"expires_at")));}
  @Override public void accept(Invite i,UUID u,Instant now){if(role(i.workspace(),u).isEmpty())db.execute("INSERT INTO workspace_members(workspace_id,user_id,role) VALUES(?,?,?) ON CONFLICT DO NOTHING",i.workspace(),u,i.role());changed(db.execute("UPDATE team_invitations SET accepted_at=?::timestamptz WHERE id=? AND accepted_at IS NULL AND revoked_at IS NULL",at(now),i.id()));}
  @Override public void member(UUID w,UUID u,String role){changed(db.execute("UPDATE workspace_members SET role=? WHERE workspace_id=? AND user_id=?",role,w,u));}
  @Override public void remove(UUID w,UUID u){changed(db.execute("DELETE FROM workspace_members WHERE workspace_id=? AND user_id=?",w,u));}
  @Override public void revokeInvitation(UUID w,UUID id){changed(db.execute("UPDATE team_invitations SET revoked_at=now() WHERE workspace_id=? AND id=? AND revoked_at IS NULL AND accepted_at IS NULL",w,id));}
  @Override public void audit(UUID w,UUID u,String action,String target,Instant now){db.execute("INSERT INTO workspace_audit(workspace_id,actor_id,action,target,at) VALUES(?,?,?,?,?::timestamptz)",w,u,action,target,at(now));}
  @Override public List<Map<String,Object>> audit(UUID w){return rows("SELECT id,actor_id,action,target,at FROM workspace_audit WHERE workspace_id=? ORDER BY id DESC LIMIT 200",w);}
  @Override public List<Map<String,Object>> organization(UUID w){return rows("SELECT id,kind,name FROM workspace_labels WHERE workspace_id=? ORDER BY kind,name",w);}
  @Override public UUID label(UUID w,String kind,String name){return db.fetchOne("INSERT INTO workspace_labels(workspace_id,kind,name) VALUES(?,?,?) ON CONFLICT(workspace_id,kind,name) DO UPDATE SET name=excluded.name RETURNING id",w,kind,name).get("id",UUID.class);}
  @Override public void removeLabel(UUID w,UUID id){changed(db.execute("DELETE FROM workspace_labels WHERE workspace_id=? AND id=?",w,id));}
  @Override public void organize(UUID w,UUID link,UUID folder,List<UUID> tags){
    if(folder!=null&&count("SELECT count(*) FROM workspace_labels WHERE workspace_id=? AND id=? AND kind='folder'",w,folder)==0)throw new DomainException("not_found");
    for(UUID tag:tags)if(count("SELECT count(*) FROM workspace_labels WHERE workspace_id=? AND id=? AND kind='tag'",w,tag)==0)throw new DomainException("not_found");
    changed(db.execute("UPDATE links SET folder_id=? WHERE workspace_id=? AND id=?",folder,w,link));db.execute("DELETE FROM link_tags WHERE link_id=?",link);for(UUID tag:new HashSet<>(tags))db.execute("INSERT INTO link_tags VALUES(?,?)",link,tag);
  }
  @Override public List<Map<String,Object>> exportLinks(UUID w){return rows("SELECT id,destination,slug,title,folder_id,coalesce((SELECT jsonb_agg(tag_id) FROM link_tags WHERE link_id=l.id),'[]'::jsonb) AS tags FROM links l WHERE workspace_id=? ORDER BY created_at,id",w);}
  private static Integration integration(Record r){return new Integration(r.get("id",UUID.class),r.get("workspace_id",UUID.class),r.get("provider",String.class),r.get("name",String.class),Sql.strings(r.get("config",JSONB.class)),r.get("credentials_cipher",String.class),r.get("endpoint_id",UUID.class),r.get("status",String.class));}
  @Override public List<Integration> integrations(UUID w){return db.fetch("SELECT * FROM integrations WHERE workspace_id=? ORDER BY created_at DESC",w).map(PostgresEcosystemAdapter::integration);}
  @Override public Optional<Integration> integration(UUID id){return db.fetchOptional("SELECT * FROM integrations WHERE id=?",id).map(PostgresEcosystemAdapter::integration);}
  @Override public void integration(Integration i){db.execute("INSERT INTO integrations(id,workspace_id,provider,name,config,credentials_cipher,endpoint_id,status) VALUES(?,?,?,?,?::jsonb,?,?,?)",i.id(),i.workspace(),i.provider(),i.name(),Sql.json(i.config()),i.credentials(),i.endpoint(),i.status());}
  @Override public void disconnect(UUID w,UUID id){var i=integration(id).filter(x->x.workspace().equals(w)).orElseThrow(()->new DomainException("not_found"));db.execute("UPDATE integrations SET status='disabled',credentials_cipher='' WHERE id=?",id);if(i.endpoint()!=null){db.execute("UPDATE webhook_endpoints SET enabled=false WHERE id=?",i.endpoint());db.execute("UPDATE webhook_deliveries SET status='cancelled' WHERE endpoint_id=? AND status IN ('pending','sending')",i.endpoint());}db.execute("UPDATE integration_events SET status='cancelled',payload='{}' WHERE integration_id=? AND status IN ('pending','sending','failed')",id);}
  @Override public void integrationError(UUID id,String error,Instant now){db.execute("UPDATE integrations SET status=?,last_error=?,last_at=?::timestamptz WHERE id=? AND status<>'disabled'",error==null?"active":"error",error,at(now),id);}
  @Override public void integrationDelivery(UUID endpoint,Integer status,Instant now){boolean ok=status!=null&&status>=200&&status<300;db.execute("UPDATE integrations SET status=?,last_error=?,last_at=?::timestamptz WHERE endpoint_id=? AND status<>'disabled'",ok?"active":"error",ok?null:status==null?"delivery_failed":"http_"+status,at(now),endpoint);}
  private static Map<String,Object> payload(EventCommand c){var m=new LinkedHashMap<String,Object>();m.put("eventId",c.eventId().toString());m.put("name",c.name());m.put("visitor",c.visitor());m.put("cid",c.cid());m.put("value",c.value());m.put("currency",c.currency());m.put("page",c.page());m.put("consent",c.consent());m.put("utm",c.utm());return m;}
  private static Incoming incoming(Record r){var m=Sql.map(r.get("payload",JSONB.class));var c=new EventCommand(UUID.fromString((String)m.get("eventId")),(String)m.get("name"),(String)m.get("visitor"),(String)m.get("cid"),m.get("value")==null?null:new java.math.BigDecimal(m.get("value").toString()),(String)m.get("currency"),(String)m.get("page"),Boolean.TRUE.equals(m.get("consent")),Map.of());return new Incoming(r.get("id",UUID.class),r.get("integration_id",UUID.class),r.get("workspace_id",UUID.class),r.get("external_id",String.class),r.get("event",String.class),c,r.get("status",String.class),r.get("attempts",Integer.class),time(r,"created_at"));}
  @Override public boolean incoming(Incoming i){return db.execute("INSERT INTO integration_events(id,integration_id,workspace_id,external_id,event,payload,created_at,next_at) VALUES(?,?,?,?,?,?::jsonb,?::timestamptz,?::timestamptz) ON CONFLICT(integration_id,external_id) DO NOTHING",i.id(),i.integration(),i.workspace(),i.externalId(),i.event(),Sql.json(payload(i.command())),at(i.at()),at(i.at()))>0;}
  @Override public List<Incoming> claimIncoming(Instant now,int limit){return db.fetch("WITH due AS (SELECT e.id FROM integration_events e JOIN integrations i ON i.id=e.integration_id WHERE e.status IN ('pending','sending') AND i.status IN ('active','error') AND e.next_at<=?::timestamptz ORDER BY e.next_at FOR UPDATE OF e SKIP LOCKED LIMIT ?) UPDATE integration_events e SET status='sending',attempts=attempts+1,next_at=?::timestamptz FROM due WHERE e.id=due.id RETURNING e.*",at(now),limit,at(now.plusSeconds(120))).map(PostgresEcosystemAdapter::incoming);}
  @Override public boolean incomingActive(UUID w,UUID id,int attempt){return count("SELECT count(*) FROM integration_events WHERE workspace_id=? AND id=? AND status='sending' AND attempts=?",w,id,attempt)>0;}
  @Override public void incomingResult(UUID id,int attempt,String error,Instant now){db.execute("UPDATE integration_events SET status=?,last_error=?,next_at=?::timestamptz WHERE id=? AND attempts=? AND status='sending'",error==null?"processed":attempt>=8?"failed":"pending",error,at(now.plusSeconds(Math.min(86400,30L*(1L<<Math.min(12,attempt))))),id,attempt);}
  @Override public void replayIncoming(UUID w,UUID id,Instant now){changed(db.execute("UPDATE integration_events e SET status='pending',attempts=0,next_at=?::timestamptz WHERE workspace_id=? AND id=? AND status='failed' AND EXISTS(SELECT 1 FROM integrations i WHERE i.id=e.integration_id AND i.status<>'disabled')",at(now),w,id));}
  @Override public Map<String,Object> radar(UUID w){return Map.of("rules",rows("SELECT id,kind,threshold,channel,link_id,created_at FROM radar_rules WHERE workspace_id=? ORDER BY created_at",w),"alerts",rows("SELECT id,kind,message,created_at FROM radar_alerts WHERE workspace_id=? ORDER BY created_at DESC,id DESC LIMIT 100",w),"health",rows("SELECT l.id,l.slug,h.status,h.checked_at FROM links l LEFT JOIN destination_health h ON h.link_id=l.id WHERE l.workspace_id=? ORDER BY h.checked_at DESC NULLS FIRST LIMIT 200",w),"reports",rows("SELECT frequency,enabled,next_at FROM scheduled_reports WHERE workspace_id=?",w));}
  @Override public UUID rule(UUID w,String kind,long threshold,String channel,String dest,UUID link,UUID endpoint,Instant now){if(link!=null&&count("SELECT count(*) FROM links WHERE workspace_id=? AND id=?",w,link)==0)throw new DomainException("not_found");return db.fetchOne("INSERT INTO radar_rules(workspace_id,kind,threshold,channel,destination_cipher,link_id,endpoint_id,created_at) VALUES(?,?,?,?,?,?,?,?::timestamptz) RETURNING id",w,kind,threshold,channel,dest,link,endpoint,at(now)).get("id",UUID.class);}
  @Override public void removeRule(UUID w,UUID id){var r=db.fetchOptional("SELECT endpoint_id FROM radar_rules WHERE workspace_id=? AND id=?",w,id).orElseThrow(()->new DomainException("not_found"));db.execute("DELETE FROM radar_rules WHERE workspace_id=? AND id=?",w,id);UUID endpoint=r.get("endpoint_id",UUID.class);if(endpoint!=null){db.execute("UPDATE webhook_endpoints SET enabled=false WHERE id=? AND workspace_id=?",endpoint,w);db.execute("UPDATE webhook_deliveries SET status='cancelled' WHERE endpoint_id=? AND status IN ('pending','sending')",endpoint);}}
  @Override public void evaluateRadar(Instant now){
    Instant since=now.minusSeconds(900),bucket=Instant.ofEpochSecond(now.getEpochSecond()/900*900);
    for(var r:db.fetch("SELECT r.* FROM radar_rules r WHERE beep_effective_right(workspace_id,'features.radar')=1 AND (channel='email' OR beep_effective_right(workspace_id,'features.insights')=1) AND (last_evaluated_at IS NULL OR last_evaluated_at<=?::timestamptz) ORDER BY last_evaluated_at NULLS FIRST,id LIMIT 1000",at(now.minusSeconds(60)))){
      UUID w=r.get("workspace_id",UUID.class),link=r.get("link_id",UUID.class);String kind=r.get("kind",String.class);
      long clicks=count("SELECT count(*) FROM click_events WHERE workspace_id=? AND (?::uuid IS NULL OR link_id=?) AND NOT is_bot AND ts>=?::timestamptz",w,link,link,at(since));
      long sales=count("SELECT count(*) FROM conversion_events WHERE workspace_id=? AND (?::uuid IS NULL OR link_id=?) AND name='sale' AND at>=?::timestamptz",w,link,link,at(since));
      long errors=kind.equals("domain_error")?count("SELECT count(*) FROM custom_domains WHERE workspace_id=? AND (dns_status='failed' OR blocked)",w):count("SELECT count(*) FROM destination_health h JOIN links l ON l.id=h.link_id WHERE l.workspace_id=? AND (?::uuid IS NULL OR l.id=?) AND checked_url=l.destination AND (h.status=0 OR h.status>=400)",w,link,link);
      db.execute("UPDATE radar_rules SET last_evaluated_at=?::timestamptz WHERE id=?",at(now),r.get("id"));
      if(!RadarPolicy.fires(kind,r.get("threshold",Long.class),clicks,0,sales,errors))continue;
      String message=kind+" · clicks="+clicks+" · sales="+sales+" · errors="+errors;
      int inserted=db.execute("INSERT INTO radar_alerts(workspace_id,rule_id,kind,message,bucket,created_at) VALUES(?,?,?,?,?::timestamptz,?::timestamptz) ON CONFLICT(rule_id,bucket) DO NOTHING",w,r.get("id"),kind,message,at(bucket),at(now));
      if(inserted>0&&r.get("channel",String.class).equals("webhook")){db.execute("INSERT INTO webhook_deliveries(workspace_id,endpoint_id,event,payload) SELECT ?,id,'radar.alert',jsonb_build_object('id',gen_random_uuid(),'type','radar.alert','createdAt',?::timestamptz,'data',jsonb_build_object('kind',?,'message',?))::text FROM webhook_endpoints WHERE id=? AND enabled",w,at(now),kind,message,r.get("endpoint_id"));}
      else if(inserted>0)db.execute("INSERT INTO ecosystem_tasks(workspace_id,channel,destination_cipher,body) VALUES(?,?,?,?)",w,r.get("channel"),r.get("destination_cipher"),message);
    }
  }
  @Override public List<Probe> claimProbes(Instant now,int limit){db.execute("INSERT INTO destination_health(link_id) SELECT l.id FROM links l WHERE l.status='active' AND beep_effective_right(l.workspace_id,'features.radar')=1 AND NOT EXISTS(SELECT 1 FROM destination_health h WHERE h.link_id=l.id) LIMIT 1000 ON CONFLICT DO NOTHING");return db.fetch("WITH due AS (SELECT h.link_id FROM destination_health h JOIN links l ON l.id=h.link_id WHERE l.status='active' AND beep_effective_right(l.workspace_id,'features.radar')=1 AND (h.next_at<=?::timestamptz OR h.checked_url IS DISTINCT FROM l.destination) ORDER BY h.next_at FOR UPDATE OF h SKIP LOCKED LIMIT ?) UPDATE destination_health h SET next_at=?::timestamptz,checked_url=l.destination FROM due JOIN links l ON l.id=due.link_id WHERE h.link_id=due.link_id RETURNING h.link_id,l.workspace_id,l.destination",at(now),limit,at(now.plusSeconds(21600))).map(r->new Probe(r.get("link_id",UUID.class),r.get("workspace_id",UUID.class),r.get("destination",String.class)));}
  @Override public void probeResult(UUID link,String url,int status,Instant now){db.execute("UPDATE destination_health SET status=?,checked_at=?::timestamptz WHERE link_id=? AND checked_url=?",status,at(now),link,url);}
  @Override public List<Task> claimTasks(Instant now,int limit){return db.fetch("WITH due AS (SELECT id FROM ecosystem_tasks WHERE status IN ('pending','sending') AND next_at<=?::timestamptz ORDER BY next_at FOR UPDATE SKIP LOCKED LIMIT ?) UPDATE ecosystem_tasks t SET status='sending',attempts=attempts+1,next_at=?::timestamptz FROM due WHERE t.id=due.id RETURNING t.*",at(now),limit,at(now.plusSeconds(120))).map(r->new Task(r.get("id",UUID.class),r.get("workspace_id",UUID.class),r.get("channel",String.class),r.get("destination_cipher",String.class),r.get("body",String.class),r.get("attempts",Integer.class)));}
  @Override public void taskResult(UUID id,int attempt,String error,Instant now){db.execute("UPDATE ecosystem_tasks SET status=?,last_error=?,next_at=?::timestamptz WHERE id=? AND attempts=? AND status='sending'",error==null?"delivered":attempt>=8?"failed":"pending",error,at(now.plusSeconds(Math.min(86400,30L*(1L<<Math.min(12,attempt))))),id,attempt);}
  @Override public void report(UUID w,String frequency,boolean enabled,Instant now){db.execute("INSERT INTO scheduled_reports VALUES(?,?,?,?::timestamptz,?::timestamptz) ON CONFLICT(workspace_id) DO UPDATE SET frequency=excluded.frequency,enabled=excluded.enabled,next_at=excluded.next_at,updated_at=excluded.updated_at",w,frequency,enabled,at(now.plusSeconds(frequency.equals("daily")?86400:604800)),at(now));}
  @Override public void scheduleReports(Instant now){
    for(var r:db.fetch("SELECT * FROM scheduled_reports WHERE enabled AND next_at<=?::timestamptz AND beep_effective_right(workspace_id,'features.reports')=1 ORDER BY next_at FOR UPDATE SKIP LOCKED LIMIT 50",at(now))){
      UUID w=r.get("workspace_id",UUID.class);String frequency=r.get("frequency",String.class);
      long seconds=frequency.equals("daily")?86400:604800;
      Instant end=now.atZone(ZoneOffset.UTC).toLocalDate().atStartOfDay(ZoneOffset.UTC).toInstant(),start=end.minusSeconds(seconds);
      long clicks=count("SELECT coalesce(sum(clicks),0) FROM rollups_daily WHERE workspace_id=? AND resource_type='link' AND dimension='total' AND day>=?::date AND day<?::date",w,start.atOffset(ZoneOffset.UTC).toLocalDate(),end.atOffset(ZoneOffset.UTC).toLocalDate());
      long sales=count("SELECT count(*) FROM conversion_events WHERE workspace_id=? AND name='sale' AND at>=?::timestamptz AND at<?::timestamptz",w,at(start),at(end));
      String body="Rapport BeepClick · "+frequency+" · "+start+" → "+end+" · clicks="+clicks+" · sales="+sales;
      db.execute("INSERT INTO ecosystem_tasks(workspace_id,channel,destination_cipher,body) VALUES(?,'email','owner',?)",w,body);
      db.execute("UPDATE scheduled_reports SET next_at=?::timestamptz WHERE workspace_id=?",at(now.plusSeconds(seconds)),w);
    }
  }
  @Override public Map<String,Object> insights(UUID w,Instant since){return Map.of("daily",rows("SELECT day,sum(clicks) AS clicks,sum(uniques) AS visitors FROM rollups_daily WHERE workspace_id=? AND resource_type='link' AND dimension='total' AND day>=?::date GROUP BY day ORDER BY day",w,since.atOffset(ZoneOffset.UTC).toLocalDate()),"segments",rows("SELECT dimension,key,sum(clicks) AS clicks FROM rollups_daily WHERE workspace_id=? AND resource_type='link' AND dimension IN ('country','device','referrer') AND day>=?::date GROUP BY dimension,key ORDER BY clicks DESC LIMIT 50",w,since.atOffset(ZoneOffset.UTC).toLocalDate()),"campaigns",rows("SELECT utm->>'source' AS source,utm->>'campaign' AS campaign,count(*) AS events,count(*) FILTER(WHERE name='sale') AS sales FROM conversion_events WHERE workspace_id=? AND at>=?::timestamptz GROUP BY utm->>'source',utm->>'campaign' ORDER BY events DESC LIMIT 50",w,at(since)));}
  @Override public Map<String,Object> affiliate(UUID u){return Map.of("account",rows("SELECT code,rate_bp,accepted_at FROM affiliates WHERE user_id=?",u),"commissions",rows("SELECT id,amount_xaf,status,available_at,paid_at,reference,created_at FROM affiliate_commissions WHERE affiliate_id=? ORDER BY created_at DESC LIMIT 200",u),"referrals",count("SELECT count(*) FROM referrals WHERE affiliate_id=?",u));}
  @Override public String joinAffiliate(UUID u,Instant now){return db.fetchOne("INSERT INTO affiliates(user_id,code,accepted_at) VALUES(?,substr(replace(gen_random_uuid()::text,'-',''),1,12),?::timestamptz) ON CONFLICT(user_id) DO UPDATE SET user_id=excluded.user_id RETURNING code",u,at(now)).get("code",String.class);}
  @Override public void referral(UUID u,UUID w,String code,Instant now){var a=db.fetchOptional("SELECT user_id FROM affiliates WHERE code=?",code).orElseThrow(()->new DomainException("not_found"));if(a.get("user_id",UUID.class).equals(u)||count("SELECT count(*) FROM payments WHERE workspace_id=? AND status='succeeded'",w)>0||count("SELECT count(*) FROM workspaces WHERE id=? AND created_at<?::timestamptz",w,at(now.minusSeconds(30L*86400)))>0)throw new DomainException("forbidden");changed(db.execute("INSERT INTO referrals VALUES(?,?,?::timestamptz) ON CONFLICT DO NOTHING",w,a.get("user_id"),at(now)));}
  @Override public void accrueCommissions(Instant now){
    db.execute("INSERT INTO affiliate_commissions(affiliate_id,payment_id,amount_xaf,status,available_at,created_at) SELECT a.user_id,p.id,(p.amount_xaf*a.rate_bp/10000)::bigint,'pending',p.paid_at+interval '30 days',?::timestamptz FROM payments p JOIN referrals r ON r.workspace_id=p.workspace_id JOIN affiliates a ON a.user_id=r.affiliate_id WHERE p.status='succeeded' AND p.paid_at>=r.created_at AND p.paid_at<r.created_at+interval '12 months' AND p.provider<>'sandbox' ON CONFLICT(payment_id) DO NOTHING",at(now));
    db.execute("UPDATE affiliate_commissions c SET status='void' FROM payments p WHERE p.id=c.payment_id AND p.status<>'succeeded' AND c.status IN ('pending','approved')");
    db.execute("UPDATE affiliate_commissions SET status='approved' WHERE status='pending' AND available_at<=?::timestamptz",at(now));
  }
  @Override public boolean submit(UUID page,String block,String email,String message,Instant now){return db.execute("INSERT INTO bio_submissions(workspace_id,page_id,block_id,email_cipher,message_cipher,consent_at) SELECT p.workspace_id,p.id,?,?,?,?::timestamptz FROM bio_pages p JOIN bio_blocks b ON b.page_id=p.id AND b.id=? WHERE p.id=? AND b.type IN ('email','form') AND beep_effective_right(p.workspace_id,'features.bio_advanced')=1 AND (SELECT count(*) FROM bio_submissions WHERE workspace_id=p.workspace_id)<10000",block,email,message,at(now),block,page)>0;}
  @Override public List<Map<String,Object>> submissions(UUID w){return rows("SELECT id,page_id,block_id,email_cipher,message_cipher,consent_at FROM bio_submissions WHERE workspace_id=? ORDER BY consent_at DESC LIMIT 200",w);}
  @Override public void eraseSubmission(UUID w,UUID id){changed(db.execute("DELETE FROM bio_submissions WHERE workspace_id=? AND id=?",w,id));}
  @Override public Map<String,Object> monitor(){return Map.of("teams",count("SELECT count(DISTINCT workspace_id) FROM workspace_members"),"integrations",rows("SELECT provider,status,count(*) AS count FROM integrations GROUP BY provider,status"),"events",rows("SELECT status,count(*) AS count FROM integration_events GROUP BY status"),"tasks",rows("SELECT status,count(*) AS count FROM ecosystem_tasks GROUP BY status"),"cohorts",rows("SELECT date_trunc('month',w.created_at) AS cohort,count(*) AS workspaces,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM click_events c WHERE c.workspace_id=w.id AND NOT c.is_bot AND c.ts>=now()-interval '30 days')) AS active30d,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM click_events c WHERE c.workspace_id=w.id AND NOT c.is_bot AND c.ts>=w.created_at+interval '90 days' AND c.ts<w.created_at+interval '120 days')) AS retained90d,count(*) FILTER(WHERE w.created_at<=now()-interval '120 days') AS mature90d FROM workspaces w WHERE w.created_at>=now()-interval '12 months' GROUP BY 1 ORDER BY 1"));}
  @Override public Map<String,Object> staffWorkspace(UUID w){if(count("SELECT count(*) FROM workspaces WHERE id=?",w)==0)throw new DomainException("not_found");return Map.of("team",team(w),"integrations",rows("SELECT id,provider,name,status,last_error,last_at FROM integrations WHERE workspace_id=? ORDER BY created_at DESC",w),"events",rows("SELECT id,integration_id,event,status,attempts,last_error,created_at FROM integration_events WHERE workspace_id=? ORDER BY created_at DESC LIMIT 100",w),"radar",radar(w),"audit",audit(w),"links",exportLinks(w),"bioPages",rows("SELECT id,slug,title,description FROM bio_pages WHERE workspace_id=?",w));}
  @Override public Map<String,Object> affiliates(){return Map.of("items",rows("SELECT a.user_id,u.email,a.code,c.id,c.amount_xaf,c.status,c.available_at,c.reference FROM affiliates a JOIN users u ON u.id=a.user_id LEFT JOIN affiliate_commissions c ON c.affiliate_id=a.user_id ORDER BY c.created_at DESC NULLS LAST LIMIT 500"));}
  @Override public void payout(UUID staff,List<UUID> ids,String reference,Instant now){for(UUID id:ids)if(db.fetchOptional("SELECT id FROM affiliate_commissions WHERE id=? AND status='approved' AND available_at<=?::timestamptz FOR UPDATE",id,at(now)).isEmpty())throw new DomainException("conflict");for(UUID id:ids)changed(db.execute("UPDATE affiliate_commissions SET status='paid',paid_at=?::timestamptz,reference=?,recorded_by=? WHERE id=? AND status='approved'",at(now),reference,staff,id));}
  @Override public Map<String,Object> content(){return Map.of("items",rows("SELECT kind,slug,locale,title,body,status,version,published_at FROM public_content ORDER BY published_at DESC"));}
  @Override public Map<String,Object> publicContent(String kind,String locale,String slug){return Map.of("items",rows("SELECT kind,slug,locale,title,CASE WHEN ?::text IS NULL THEN '' ELSE body END AS body,version,published_at FROM public_content WHERE status='published' AND kind=? AND locale=? AND (?::text IS NULL OR slug=?) ORDER BY published_at DESC,slug LIMIT 100",slug,kind,locale,slug,slug));}
  @Override public void publish(UUID staff,Map<String,Object> p,Instant now){int n=db.execute("INSERT INTO public_content(kind,slug,locale,title,body,status,version,published_by,published_at) VALUES(?,?,?,?,?,?,?, ?,?::timestamptz) ON CONFLICT(kind,slug,locale) DO UPDATE SET title=excluded.title,body=excluded.body,status=excluded.status,version=excluded.version,published_by=excluded.published_by,published_at=excluded.published_at WHERE public_content.version<excluded.version",p.get("kind"),p.get("slug"),p.get("locale"),p.get("title"),p.get("body"),p.get("status"),p.get("version"),staff,at(now));if(n==0)throw new DomainException("conflict");}
  @Override public void retention(Instant now){db.execute("DELETE FROM team_invitations WHERE expires_at<?::timestamptz",at(now.minusSeconds(30L*86400)));db.execute("DELETE FROM integration_events WHERE created_at<?::timestamptz",at(now.minusSeconds(30L*86400)));db.execute("DELETE FROM ecosystem_tasks WHERE created_at<?::timestamptz",at(now.minusSeconds(30L*86400)));db.execute("DELETE FROM radar_alerts WHERE created_at<?::timestamptz",at(now.minusSeconds(90L*86400)));db.execute("DELETE FROM bio_submissions WHERE consent_at<?::timestamptz",at(now.minusSeconds(90L*86400)));}
}
